#include "odo.h"
#include "config.h"
#include "odo_sim.h"
#include "odo_split.h"
#include "utils.h"
#include "hardware/pio.h"
#include "pico/critical_section.h"
#include "pico/stdlib.h"
#include "quadrature_encoder.pio.h"   // generated by pico_generate_pio_header
#include <cmath>
#include <cstdlib>

// Front encoder on PIO0, state machine 0. A/B must be consecutive GPIOs
// (A = FRONT_ENCODER_A_PIN, B = A+1); config uses GP10/GP11.
static PIO  s_pio = pio0;
static uint s_sm  = 0;

// Everything below is touched only inside s_cs — both cores read the encoder
// (core1 via poseUpdate, core0 via the state machine and bench tools).
static critical_section_t s_cs;
static int32_t  s_lastRaw = 0;    // newest raw PIO count
static DirSplit s_split;          // counts since odoZero(), split by direction

// Bench dry run (odoSimSet): the split is fed from the simulated roller instead,
// and the real encoder's net travel is kept so a car on the floor is caught.
static bool     s_sim         = false;
static SimWheel s_simWheel;
static int64_t  s_simEmitted  = 0;    // whole simulated counts handed to the split
static int32_t  s_simRealNet  = 0;    // real counts since the dry run began
static uint64_t s_simLastUs   = 0;

// Speed estimator state: core0 only (see odo.h), so no synchronisation.
static float    s_speedMps      = 0.0f;
static float    s_lastSpeedDist = 0.0f;
static uint64_t s_lastSpeedUs   = 0;

void odoInit() {
  critical_section_init(&s_cs);
  pio_add_program(s_pio, &quadrature_encoder_program);
  // last arg 0 = max count rate (0 -> as fast as possible)
  quadrature_encoder_program_init(s_pio, s_sm, FRONT_ENCODER_A_PIN, 0);
}

// Drain the PIO FIFO, take one FRESH sample, and feed the change since the last
// read to the direction split. Must be called with s_cs held.
//
// The PIO pushes the count with `push noblock`: once the FIFO is full, newer
// counts are DROPPED, so everything in it dates from just after the previous
// read. Draining alone returns a stale count; the one after the drain is current
// (the PIO pushes every ~4-10 cycles). That is what the stock helper's final
// blocking get is for. Here every wait is BOUNDED instead: drain exactly the
// level read first (an unbounded `while (!empty)` can chase the refill forever),
// then wait a bounded spin for the fresh entry, so a stopped state machine can
// never hang the caller.
static void sampleLocked() {
  int32_t v = s_lastRaw;
  int n = (int)pio_sm_get_rx_fifo_level(s_pio, s_sm);
  while (n-- > 0) v = (int32_t)pio_sm_get(s_pio, s_sm);
  for (int i = 0; i < ODO_FRESH_SPIN && pio_sm_is_rx_fifo_empty(s_pio, s_sm); i++) {}
  if (!pio_sm_is_rx_fifo_empty(s_pio, s_sm)) v = (int32_t)pio_sm_get(s_pio, s_sm);
  const int32_t realDelta = ENCODER_SIGN * (v - s_lastRaw);
  s_lastRaw = v;
  if (!s_sim) {
    s_split.add(realDelta, ODO_DIR_HYST_COUNTS);
    return;
  }
  // Dry run: advance the model to now on the current drive command, and pass on
  // the whole counts it has rolled. Both cores sample often (core1 at the
  // estimator rate), so the steps stay short.
  s_simRealNet += realDelta;
  const uint64_t now = to_us_since_boot(get_absolute_time());
  DriveMode mode;
  float pct;
  driveCommand(mode, pct);
  s_simWheel.step((float)(now - s_simLastUs) * 1e-6f, mode, pct, M_PER_COUNT, M_PER_COUNT_REV_EFF);
  s_simLastUs = now;
  const int64_t emitted = (int64_t)std::floor(s_simWheel.counts);
  s_split.add((int32_t)(emitted - s_simEmitted), ODO_DIR_HYST_COUNTS);
  s_simEmitted = emitted;
}

long odoCountRaw() {
  critical_section_enter_blocking(&s_cs);
  sampleLocked();
  const int32_t v = s_lastRaw;
  critical_section_exit(&s_cs);
  return v;
}

long odoCountSigned() {
  critical_section_enter_blocking(&s_cs);
  sampleLocked();
  // In a dry run the brake's motion check must see the simulated roller too.
  const long c = s_sim ? (long)s_simEmitted : ENCODER_SIGN * (long)s_lastRaw;
  critical_section_exit(&s_cs);
  return c;
}

void odoSimSet(bool on) {
  critical_section_enter_blocking(&s_cs);
  sampleLocked();                 // settle the old source up to now first
  s_sim        = on;
  s_simWheel   = SimWheel{};
  s_simEmitted = 0;
  s_simRealNet = 0;
  s_simLastUs  = to_us_since_boot(get_absolute_time());
  critical_section_exit(&s_cs);
}

bool odoSimActive() { return s_sim; }

float odoSimRealMotionM() {
  critical_section_enter_blocking(&s_cs);
  sampleLocked();
  const int32_t n = s_simRealNet;
  critical_section_exit(&s_cs);
  return (float)std::abs(n) * M_PER_COUNT;
}

void odoZero() {
  critical_section_enter_blocking(&s_cs);
  sampleLocked();
  s_split = DirSplit{};
  critical_section_exit(&s_cs);
  // The distance reference just moved, so the speed estimate must restart too;
  // otherwise its next sample sees the whole offset as one jump. (Both are core0
  // state — odoZero is only ever called from core0.)
  s_speedMps      = 0.0f;
  s_lastSpeedDist = 0.0f;
  s_lastSpeedUs   = to_us_since_boot(get_absolute_time());
}

DirSplit odoSnapshot() {
  critical_section_enter_blocking(&s_cs);
  sampleLocked();
  const DirSplit split = s_split;
  critical_section_exit(&s_cs);
  return split;
}

float odoDistanceM() {
  // M_PER_COUNT is 0 until calibrated, which reads 0 distance — sm.cpp refuses to
  // arm in that state, so it can't turn into a runaway.
  return odoSnapshot().metres(M_PER_COUNT, M_PER_COUNT_REV_EFF);
}

void odoSpeedReset() {
  s_speedMps      = 0.0f;
  s_lastSpeedDist = odoDistanceM();
  s_lastSpeedUs   = to_us_since_boot(get_absolute_time());
}

void odoSpeedTick(float distM) {
  const uint64_t now = to_us_since_boot(get_absolute_time());
  if (s_lastSpeedUs == 0) {          // never reset: seed, don't emit
    s_speedMps      = 0.0f;
    s_lastSpeedDist = distM;
    s_lastSpeedUs   = now;
    return;
  }
  const float dt = (float)(now - s_lastSpeedUs) * 1e-6f;
  if (dt < SPEED_SAMPLE_MIN_S) return;   // too soon — quantisation would swamp ds/dt

  const float raw  = (distM - s_lastSpeedDist) / dt;
  s_lastSpeedDist  = distM;
  s_lastSpeedUs    = now;
  s_speedMps = utils::lowpass(s_speedMps, raw, dt, SPEED_FILTER_TAU_S);
}

float odoSpeedMps() {
  return s_speedMps;
}
